def make(n):
    # single very long integer literal, e.g. "111...1" (n digits)
    return [["1" * n]]

def make(n):
    # pattern: "1+2+3+..."  (n numbers, n‑1 plus signs)
    parts = []
    for i in range(n):
        parts.append(str((i % 9) + 1))   # digits 1‑9
        if i != n-1:
            parts.append('+')
    text = ''.join(parts)
    return [[text]]

def make(n):
    # produce '1+2+3+...+' with n numbers
    parts = []
    for i in range(1, n+1):
        parts.append(str(i % 10))
        if i != n:
            parts.append('+')
    s = ''.join(parts)
    return [[s]]

