def make(n):
    # produce n distinct valid dimension strings
    units = ["cm", "in", "pt", "mm", "ex", "em"]
    vals = []
    for i, u in zip(range(n), itertools.cycle(units)):
        # alternate integer and decimal forms
        if i % 2 == 0:
            vals.append(f"{i+1}{u}")
        else:
            vals.append(f"{i+1}.5{u}")
    # each element is a single‑argument call list for validate_typst_dimension
    return [[v] for v in vals]

