def make(n):
    # a dict with n distinct string keys, all mapping to the same simple value
    d = {f'k{i}': i for i in range(n)}
    return [[d, d]]

def make(n):
    # dict1: keys k0..k{n-1}
    # dict2: keys k0..k{n-2} plus 'extra' -> same length, 1 common key
    d1 = {f'k{i}': i for i in range(n)}
    d2 = {f'k{i}': i for i in range(n-1)}
    d2['extra'] = n
    return [[d1, d2]]

def make(n):
    """Generate up to 8 distinct expressions; each grows with n."""
    out = []
    for i in range(min(max(n, 1), 8)):
        # a simple unique expression, padded to length ~n
        base = f"x{i}+{i}*y{i}"
        if n > 0:
            base += "+0" * (n // 2)
        out.append([base])
    return out
